insert into public.materials (material_id,week_id,material_no,order_no,title,content_html,resource_url,visible,updated_at) values
  ('MAT001','W01',1,1,'Konsep Dasar Metode Ilmiah','<h2>Penelitian sebagai Proses Ilmiah</h2><p>Orientasi mata kuliah, kontrak belajar, kebenaran ilmiah, fungsi metode ilmiah, dan pentingnya penelitian pendidikan fisika bagi calon guru.</p><h3>Pertanyaan pemantik</h3><p>Apa yang membedakan masalah kelas biasa dengan masalah yang layak diteliti?</p>','',true,now()),
  ('MAT002','W02',2,1,'Isu Penelitian Pendidikan Fisika','<h2>Dari Fenomena ke Isu Penelitian</h2><p>Telusuri fenomena pembelajaran fisika, bukti empiris, miskonsepsi, asesmen, media, pedagogi, teknologi, dan konteks sekolah untuk menemukan isu yang relevan.</p><p><strong>Target:</strong> satu tema yang didukung minimal lima artikel relevan.</p>','',true,now()),
  ('MAT003','W03',3,1,'Pendekatan dan Jenis Penelitian','<h2>Memilih Pendekatan berdasarkan Masalah</h2><p>Bandingkan pendekatan kuantitatif, kualitatif, survei, eksperimen/kuasi eksperimen, R&D, dan desain lain yang relevan. Pemilihan metode harus mengikuti pertanyaan penelitian.</p>','',true,now()),
  ('MAT004','W04',4,1,'Sampling, Variabel, dan Skala Pengukuran','<h2>Apa yang Diukur dan Siapa yang Diteliti?</h2><p>Bahas variabel/fokus, data, definisi operasional, skala pengukuran, serta hubungan awal dengan sampel penelitian.</p>','',true,now()),
  ('MAT005','W05',5,1,'Anggapan Dasar dan Hipotesis','<h2>Dari Argumentasi ke Hipotesis</h2><p>Pelajari anggapan dasar, pengertian dan jenis hipotesis, perumusan hipotesis, serta kondisi ketika penelitian tidak menggunakan hipotesis.</p>','',true,now()),
  ('MAT006','W06',6,1,'Populasi, Sampel, dan Teknik Sampling','<h2>Menentukan Representasi Subjek Penelitian</h2><p>Pelajari populasi, sampel, ukuran sampel, probability/non-probability sampling, serta alasan metodologis pemilihannya.</p>','',true,now()),
  ('MAT007','W07',7,1,'Penelitian Kualitatif','<h2>Memahami Makna dan Konteks</h2><p>Bandingkan kualitatif dan kuantitatif; tentukan fokus, rumusan masalah, informan/subjek, teknik pengumpulan data, kredibilitas, dan langkah dasar penelitian kualitatif.</p>','',true,now()),
  ('MAT008','W08',8,1,'Evaluasi Tengah Semester','<h2>Evaluasi Tengah Semester</h2><p>Evaluasi mengintegrasikan materi pertemuan 1–7. Instruksi teknis UTS dapat diedit dosen melalui menu Kelola Aktivitas tanpa mengubah kode LMS.</p>','',true,now()),
  ('MAT009','W09',9,1,'Penelitian Kuantitatif: Eksperimen','<h2>Eksperimen dalam Pendidikan Fisika</h2><p>Pelajari variabel perlakuan, kontrol, desain eksperimen, validitas internal, instrumen, prosedur, dan keterkaitan desain dengan analisis data.</p>','',true,now()),
  ('MAT010','W10',10,1,'Penelitian Kuantitatif: Kuasi Eksperimen','<h2>Kuasi Eksperimen di Kelas Nyata</h2><p>Pelajari karakteristik kuasi eksperimen, kelompok yang sudah terbentuk, desain pretest-posttest, ancaman validitas, instrumen, dan rencana analisis.</p>','',true,now()),
  ('MAT011','W11',11,1,'Penelitian Pengembangan (R&D)','<h2>Penelitian yang Menghasilkan Produk</h2><p>Bahas konsep R&D, karakteristik, model/tahapan pengembangan, validasi ahli, uji coba, revisi, dan instrumen penelitian pengembangan.</p>','',true,now()),
  ('MAT012','W12',12,1,'Penelitian Tindakan Kelas','<h2>Perbaikan Pembelajaran melalui Siklus Tindakan</h2><p>Bahas masalah kelas, perencanaan, tindakan, observasi, refleksi, indikator keberhasilan, dan instrumen PTK.</p>','',true,now()),
  ('MAT013','W13',13,1,'Analisis Data Penelitian','<h2>Dari Data ke Kesimpulan</h2><p>Tentukan analisis berdasarkan pertanyaan/hipotesis, desain, jenis data, dan asumsi. Latih deskripsi, uji coba, analisis, serta interpretasi hasil.</p>','',true,now()),
  ('MAT014','W14',14,1,'Analisis Artikel Jurnal Nasional dan Internasional','<h2>Literatur sebagai Evidence</h2><p>Telusuri artikel relevan, baca kritis masalah, teori, metode, temuan, kekuatan, keterbatasan, dan posisi penelitian untuk membangun research gap serta state of the art.</p>','',true,now()),
  ('MAT015','W15',15,1,'Presentasi Proposal atau Outline Penelitian','<h2>Defend Your Research Design</h2><p>Presentasikan judul, latar belakang, gap, rumusan masalah, teori, metode, instrumen, dan analisis data. Gunakan pertanyaan dan feedback sebagai dasar revisi.</p>','',true,now()),
  ('MAT016','W16',16,1,'Evaluasi Akhir Semester dan Finalisasi Proposal','<h2>Proposal sebagai Produk Integratif</h2><p>Finalisasi proposal BAB I–III, lakukan audit konsistensi masalah–tujuan–teori–metode–instrumen–analisis, lalu refleksikan kesiapan menuju tugas akhir.</p>','',true,now())
insert into public.activities (activity_id,week_id,type,title,description_html,mode,max_score,due_at,visible,allow_comments,project_code,created_at,updated_at) values
  ('TASK1_ISSUE','W02','assignment','Tugas 1 — Analisis Isu melalui Kajian Pustaka','<p><strong>CPMK 1.</strong> Lakukan kajian pustaka minimal <strong>5 artikel dengan tema yang sama</strong>. Identifikasi fenomena/permasalahan pembelajaran fisika, analisis penyebab/akar masalah, tentukan topik/judul awal, dan bangun argumentasi akademik dengan referensi relevan.</p>','individual',100,null,true,true,'',now(),now()),
  ('TASK2_GAP','W03','assignment','Tugas 2 — Analisis Masalah, GAP, State of the Art & Artikel Penelitian','<p><strong>CPMK 1.</strong> Analisis masalah, gap, dan state of the art dari isu yang diperoleh. Dokumen sumber juga meminta mahasiswa memilih satu artikel penelitian pendidikan fisika dan menganalisis pendekatan, jenis/desain, subjek, instrumen, analisis data, kontribusi, kelebihan, dan keterbatasannya.</p>','individual',100,null,true,true,'',now(),now()),
  ('UTS_METOPEN','W08','assignment','UTS — Evaluasi Tengah Semester','<p>Evaluasi Tengah Semester sesuai instruksi dosen. RPS menyebut EVALUASI TENGAH SEMESTER tetapi tidak merinci format/bobot terpisah; instruksi ini dapat diedit melalui Kelola Aktivitas.</p>','individual',100,null,true,true,'',now(),now()),
  ('TASK3_DESIGN','W11','assignment','Tugas 3 — Rancangan Desain Penelitian Pendidikan Fisika','<p><strong>CPMK 2.</strong> Susun rancangan penelitian berdasarkan topik yang telah dipilih. Tentukan rumusan masalah/tujuan, variabel atau fokus, desain penelitian (kualitatif/kuantitatif/R&D sesuai kebutuhan), populasi-sampel/teknik sampling bila relevan, serta rencana analisis data.</p>','individual',100,null,true,true,'',now(),now()),
  ('TASK4_INSTRUMENT','W12','assignment','Tugas 4 — Pengembangan Instrumen Penelitian','<p><strong>CPMK 2.</strong> Kembangkan instrumen sesuai rancangan penelitian: definisi variabel/fokus dan indikator, kisi-kisi, butir instrumen, serta rencana uji validitas dan reliabilitas/kualitas instrumen.</p>','individual',100,null,true,true,'',now(),now()),
  ('TASK5_PROPOSAL','W15','assignment','Tugas 5 — Proposal Penelitian BAB I–BAB III','<p><strong>CPMK 3.</strong> Susun proposal penelitian pendidikan fisika BAB I–BAB III secara sistematis, termasuk judul, latar belakang dan identifikasi masalah, rumusan masalah/tujuan/manfaat, kajian teori dan penelitian relevan, desain/metode, instrumen dan teknik pengumpulan data, teknik analisis data, serta sitasi/referensi.</p>','individual',100,null,true,true,'',now(),now()),
  ('UAS_METOPEN','W16','assignment','UAS — Evaluasi Akhir Semester / Finalisasi Proposal','<p>Evaluasi Akhir Semester dan finalisasi proposal sesuai instruksi dosen. RPS menyebut EVALUASI AKHIR SEMESTER tanpa rincian format/bobot terpisah.</p>','individual',100,null,true,true,'',now(),now()),
  ('DISC_ISSUE','W02','discussion','Diskusi — Kapan Fenomena Layak Menjadi Masalah Penelitian?','','individual',100,null,true,true,'',now(),now()),
  ('DISC_QUAL','W07','discussion','Diskusi — Kapan Memilih Pendekatan Kualitatif?','','individual',100,null,true,true,'',now(),now()),
  ('DISC_QUASI','W10','discussion','Diskusi — Eksperimen atau Kuasi Eksperimen?','','individual',100,null,true,true,'',now(),now()),
  ('DISC_GAP','W14','discussion','Diskusi — Apakah Research Gap Saya Benar-benar Gap?','','individual',100,null,true,true,'',now(),now())
insert into public.discussions (discussion_id,activity_id,prompt_html,min_posts,grading_mode,updated_at) values
  ('D_ISSUE','DISC_ISSUE','<p>Ajukan satu fenomena pembelajaran fisika yang Anda anggap layak diteliti. Jelaskan bukti awal, siapa yang terdampak, mengapa penting, dan apa yang masih belum diketahui. Tanggapi minimal satu post teman.</p>',2,'manual',now()),
  ('D_QUAL','DISC_QUAL','<p>Berikan satu masalah pendidikan fisika yang lebih tepat dijawab secara kualitatif daripada kuantitatif. Jelaskan fokus, calon informan/subjek, dan jenis evidence yang ingin diperoleh.</p>',2,'manual',now()),
  ('D_QUASI','DISC_QUASI','<p>Dalam konteks kelas nyata, kapan kuasi eksperimen lebih realistis daripada eksperimen murni? Jelaskan konsekuensi terhadap validitas dan interpretasi hasil.</p>',2,'manual',now()),
  ('D_GAP','DISC_GAP','<p>Tuliskan klaim research gap Anda dalam 2–3 kalimat dan sebutkan evidence artikel yang mendukung. Tanggapi klaim teman: apakah benar gap, sekadar topik baru, atau hanya keterbatasan studi sebelumnya?</p>',2,'manual',now())
insert into public.rubrics (rubric_id,activity_id,name,criteria_json,updated_at) values
  ('R_TASK1','TASK1_ISSUE','Rubrik Tugas 1 — Analisis Isu','{"criteria":[{"id":"T1C1","name":"Identifikasi fenomena/permasalahan penelitian","weight":25,"levels":[{"score":4,"description":"Masalah spesifik, aktual, relevan dengan pembelajaran fisika, disertai bukti/fakta pendukung."},{"score":3,"description":"Masalah cukup jelas dan relevan, tetapi bukti pendukung masih terbatas."},{"score":2,"description":"Masalah masih umum dan belum menunjukkan fokus penelitian."},{"score":1,"description":"Tidak mampu mengidentifikasi masalah penelitian."}]},{"id":"T1C2","name":"Analisis penyebab dan akar masalah","weight":25,"levels":[{"score":4,"description":"Menjelaskan penyebab secara mendalam berdasarkan teori atau penelitian terdahulu."},{"score":3,"description":"Menjelaskan penyebab tetapi belum dikaitkan dengan teori secara kuat."},{"score":2,"description":"Analisis penyebab masih terbatas."},{"score":1,"description":"Tidak ada analisis penyebab masalah."}]},{"id":"T1C3","name":"Penentuan topik/judul penelitian","weight":25,"levels":[{"score":4,"description":"Judul jelas, spesifik, memiliki variabel/fokus tepat, dan sesuai bidang pendidikan fisika."},{"score":3,"description":"Judul cukup sesuai tetapi masih perlu penyempurnaan."},{"score":2,"description":"Judul terlalu luas atau kurang menggambarkan penelitian."},{"score":1,"description":"Judul tidak sesuai dengan masalah."}]},{"id":"T1C4","name":"Argumentasi akademik dan referensi","weight":25,"levels":[{"score":4,"description":"Menggunakan sumber ilmiah relevan dan memberikan argumentasi akademik yang kuat."},{"score":3,"description":"Menggunakan beberapa referensi tetapi analisis belum mendalam."},{"score":2,"description":"Referensi terbatas dan argumentasi kurang kuat."},{"score":1,"description":"Tidak menggunakan referensi ilmiah."}]}],"note":"","source_weight_total":100}'::jsonb,now()),
  ('R_TASK2','TASK2_GAP','Rubrik Tugas 2 — Analisis GAP & Artikel','{"criteria":[{"id":"T2C1","name":"Pemahaman masalah, gap, dan tujuan penelitian","weight":25,"levels":[{"score":4,"description":"Menjelaskan masalah, gap, dan tujuan secara tepat dan mendalam."},{"score":3,"description":"Menjelaskan masalah dan tujuan dengan cukup tepat."},{"score":2,"description":"Hanya menjelaskan masalah secara deskriptif."},{"score":1,"description":"Tidak memahami masalah penelitian."}]},{"id":"T2C2","name":"Analisis metodologi penelitian","weight":30,"levels":[{"score":4,"description":"Menganalisis pendekatan, desain, subjek, instrumen, dan analisis data serta kesesuaiannya."},{"score":3,"description":"Menjelaskan sebagian besar komponen metode penelitian."},{"score":2,"description":"Analisis metode terbatas pada deskripsi."},{"score":1,"description":"Tidak mampu menjelaskan metode penelitian."}]},{"id":"T2C3","name":"Evaluasi kelebihan dan keterbatasan penelitian","weight":25,"levels":[{"score":4,"description":"Memberikan kritik akademik berdasarkan teori dan metodologi penelitian."},{"score":3,"description":"Memberikan evaluasi tetapi masih sederhana."},{"score":2,"description":"Evaluasi hanya berupa pendapat pribadi."},{"score":1,"description":"Tidak memberikan evaluasi."}]},{"id":"T2C4","name":"Sistematika laporan dan kualitas akademik","weight":20,"levels":[{"score":4,"description":"Laporan sistematis, bahasa ilmiah, referensi relevan, dan sesuai kaidah akademik."},{"score":3,"description":"Laporan cukup sistematis dengan beberapa kekurangan."},{"score":2,"description":"Struktur laporan kurang rapi."},{"score":1,"description":"Laporan tidak memenuhi standar akademik."}]}],"note":"","source_weight_total":100}'::jsonb,now()),
  ('R_TASK3','TASK3_DESIGN','Rubrik Tugas 3 — Rancangan Desain Penelitian','{"criteria":[{"id":"T3C1","name":"Rumusan masalah dan tujuan penelitian","weight":20,"levels":[{"score":4,"description":"Rumusan sangat jelas, spesifik, terukur, dan konsisten dengan tujuan."},{"score":3,"description":"Rumusan cukup jelas tetapi masih perlu penyempurnaan."},{"score":2,"description":"Rumusan masih umum."},{"score":1,"description":"Tidak mampu merumuskan masalah."}]},{"id":"T3C2","name":"Identifikasi variabel penelitian","weight":25,"levels":[{"score":4,"description":"Variabel bebas, terikat, dan definisi operasional ditentukan dengan sangat tepat."},{"score":3,"description":"Variabel tepat tetapi definisi operasional belum lengkap."},{"score":2,"description":"Variabel kurang tepat atau belum jelas."},{"score":1,"description":"Tidak memahami variabel penelitian."}]},{"id":"T3C3","name":"Pemilihan desain penelitian","weight":15,"levels":[{"score":4,"description":"Desain sangat sesuai dengan masalah/tujuan dan disertai alasan."},{"score":3,"description":"Desain sesuai tetapi alasan pemilihan kurang kuat."},{"score":2,"description":"Desain kurang sesuai dengan masalah."},{"score":1,"description":"Tidak mampu menentukan desain penelitian."}]},{"id":"T3C4","name":"Populasi, sampel, dan teknik sampling","weight":15,"levels":[{"score":4,"description":"Menentukan populasi, sampel, dan teknik sampling secara tepat serta argumentatif."},{"score":3,"description":"Komponen sampling cukup tepat."},{"score":2,"description":"Penentuan sampel kurang sesuai."},{"score":1,"description":"Tidak memahami konsep sampling."}]},{"id":"T3C5","name":"Rencana analisis data","weight":25,"levels":[{"score":4,"description":"Teknik analisis sesuai dengan desain dan hipotesis penelitian."},{"score":3,"description":"Analisis data cukup sesuai."},{"score":2,"description":"Analisis data kurang tepat."},{"score":1,"description":"Tidak menentukan analisis data."}]}],"note":"Bobot rubrik LMS telah disesuaikan menjadi 100% atas keputusan dosen; Rencana Analisis Data berbobot 25%.","source_weight_total":100}'::jsonb,now()),
  ('R_TASK4','TASK4_INSTRUMENT','Rubrik Tugas 4 — Pengembangan Instrumen','{"criteria":[{"id":"T4C1","name":"Definisi variabel dan indikator penelitian","weight":25,"levels":[{"score":4,"description":"Definisi variabel jelas berdasarkan teori dan indikator sesuai konstruk."},{"score":3,"description":"Definisi cukup jelas dan indikator cukup sesuai."},{"score":2,"description":"Definisi dan indikator kurang lengkap."},{"score":1,"description":"Tidak mampu menentukan indikator."}]},{"id":"T4C2","name":"Penyusunan kisi-kisi instrumen","weight":25,"levels":[{"score":4,"description":"Kisi-kisi lengkap, sistematis, dan menunjukkan hubungan indikator dengan item."},{"score":3,"description":"Kisi-kisi cukup lengkap tetapi masih ada kekurangan."},{"score":2,"description":"Kisi-kisi belum sistematis."},{"score":1,"description":"Tidak membuat kisi-kisi."}]},{"id":"T4C3","name":"Kualitas butir instrumen","weight":25,"levels":[{"score":4,"description":"Butir sesuai indikator, jelas, tidak bias, dan sangat sesuai."},{"score":3,"description":"Butir cukup sesuai tetapi masih terdapat beberapa kelemahan."},{"score":2,"description":"Sebagian butir belum sesuai indikator."},{"score":1,"description":"Butir instrumen tidak sesuai."}]},{"id":"T4C4","name":"Perencanaan uji validitas dan reliabilitas","weight":25,"levels":[{"score":4,"description":"Menjelaskan validasi ahli, validitas empiris, dan reliabilitas secara tepat."},{"score":3,"description":"Menjelaskan sebagian prosedur pengujian."},{"score":2,"description":"Penjelasan masih terbatas."},{"score":1,"description":"Tidak memahami validitas dan reliabilitas."}]}],"note":"","source_weight_total":100}'::jsonb,now()),
  ('R_TASK5','TASK5_PROPOSAL','Rubrik Tugas 5 — Proposal BAB I–III','{"criteria":[{"id":"T5C1","name":"Kesesuaian dan kualitas judul penelitian","weight":10,"levels":[{"score":4,"description":"Judul spesifik, jelas, menggambarkan variabel/fokus, dan sesuai bidang pendidikan fisika."},{"score":3,"description":"Judul cukup jelas dan sesuai tetapi perlu penyempurnaan."},{"score":2,"description":"Judul terlalu luas dan belum menunjukkan fokus."},{"score":1,"description":"Judul tidak menggambarkan penelitian yang akan dilakukan."}]},{"id":"T5C2","name":"Latar belakang dan identifikasi masalah","weight":20,"levels":[{"score":4,"description":"Latar belakang sistematis berdasarkan fenomena, data empiris, teori, dan menunjukkan urgensi penelitian."},{"score":3,"description":"Cukup jelas dan didukung teori, tetapi analisis masalah belum mendalam."},{"score":2,"description":"Masih berupa deskripsi umum tanpa menunjukkan gap penelitian."},{"score":1,"description":"Tidak menunjukkan masalah penelitian."}]},{"id":"T5C3","name":"Rumusan masalah, tujuan, dan manfaat penelitian","weight":15,"levels":[{"score":4,"description":"Rumusan jelas sesuai latar belakang, tujuan terukur, dan manfaat teoritis/praktis relevan."},{"score":3,"description":"Rumusan dan tujuan cukup sesuai tetapi belum konsisten sepenuhnya."},{"score":2,"description":"Rumusan masih umum dan kurang fokus."},{"score":1,"description":"Tidak terdapat keterkaitan antara masalah dan tujuan."}]},{"id":"T5C4","name":"Kajian teori dan penelitian relevan","weight":15,"levels":[{"score":4,"description":"Menggunakan teori relevan, sumber mutakhir, dan menunjukkan posisi penelitian dibanding penelitian sebelumnya."},{"score":3,"description":"Kajian cukup relevan tetapi hubungan dengan penelitian masih terbatas."},{"score":2,"description":"Referensi terbatas dan hanya berupa rangkuman teori."},{"score":1,"description":"Tidak menggunakan kajian teori yang memadai."}]},{"id":"T5C5","name":"Ketepatan desain/metode penelitian","weig