-- METOPEN PFIS v2.0 — seed konten inti untuk instalasi Supabase baru
-- Jalankan setelah supabase/schema.sql. Aman dijalankan ulang (upsert).

on conflict (week_id) do update set
  week_no=excluded.week_no,
  title=excluded.title,
  summary_html=excluded.summary_html,
  open_at=excluded.open_at,
  close_at=excluded.close_at,
  visible=excluded.visible,
  updated_at=excluded.updated_at;

on conflict (material_id) do update set
  week_id=excluded.week_id,
  material_no=excluded.material_no,
  order_no=excluded.order_no,
  title=excluded.title,
  content_html=excluded.content_html,
  resource_url=excluded.resource_url,
  visible=excluded.visible,
  updated_at=excluded.updated_at;

on conflict (activity_id) do update set
  week_id=excluded.week_id,
  type=excluded.type,
  title=excluded.title,
  description_html=excluded.description_html,
  mode=excluded.mode,
  max_score=excluded.max_score,
  due_at=excluded.due_at,
  visible=excluded.visible,
  allow_comments=excluded.allow_comments,
  project_code=excluded.project_code,
  created_at=excluded.created_at,
  updated_at=excluded.updated_at;

on conflict (discussion_id) do update set
  activity_id=excluded.activity_id,
  prompt_html=excluded.prompt_html,
  min_posts=excluded.min_posts,
  grading_mode=excluded.grading_mode,
  updated_at=excluded.updated_at;

on conflict (rubric_id) do update set
  activity_id=excluded.activity_id,
  name=excluded.name,
  criteria_json=excluded.criteria_json,
  updated_at=excluded.updated_at;

